import React from 'react';
import { Column, Hooks } from 'react-table';

import Colors from '@dynatrace/strato-design-tokens/colors';
import { adjustFractionDigits, format, units } from '@dynatrace-sdk/units';

import {
  datelikeCompare,
  numberlikeCompare,
  stringlikeCompare,
} from './compare-functions.js';
import { meterBarChart } from './meterbar-column-type.js';
import type { Timeseries } from '../../../charts/core/types/timeseries.js';
import { Sparkline } from '../../../charts/sparkline/Sparkline.js';
import { _formatDate } from '../../../core/utils/create-datetime-default-formatter.js';
import { _convertToNumberIfPureNumber } from '../../../core/utils/string-utils.js';
import type {
  ColumnType,
  CompareRows,
  MeterbarColumnConfig,
  SparklineColumnConfig,
} from '../../types/shared-table-types.js';

// Table typings are still based on community types which are not that great,
// need to disable no-explicit-any for the plugin file.
/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/ban-types */

/** Defines props added to columns when useColumnTypes plugin hook is used. */
export interface UseColumnTypesColumnOptions {
  /** Each column type is displayed and sorted differently. */
  columnType?: ColumnType;
}

type Alignment = 'left' | 'center' | 'right';
/**
 * Apparently it is not possible to override a type in react-table-config.d.ts unless it's an interface.
 * Unfortunately Column is a type so we have to cast to ExtendedColumn type so we can access these properties.
 */
type ExtendedColumn<D extends {}> = Column<D> & {
  sortType?: CompareRows;
  columnType?: ColumnType;
  alignment?: Alignment;
  columns?: ExtendedColumn<D>[];
  config: D;
  Cell?: any;
  disableSortBy?: boolean;
};

/** applies correct renderer and sorting depending on the column type */
function applyColumnTypes<D extends {}>(columns: Column<D>[]): Column<D>[] {
  const typedColumns = columns as ExtendedColumn<Record<string, unknown>>[];

  for (const column of typedColumns) {
    if (column.columnType === 'sparkline' || column.columnType === 'meterbar') {
      column.disableSortBy = true;
    }
    column.sortType = column.sortType ?? getSortType(column.columnType);

    if (column.Cell) {
      continue;
    }

    const subColumns = column.columns;

    if (subColumns) {
      for (const subColumn of subColumns) {
        if (subColumn.Cell || !subColumn.columnType) {
          continue;
        }

        subColumn.alignment = subColumn.alignment
          ? subColumn.alignment
          : getAlignmentBasedOnType(subColumn.columnType);
        subColumn.sortType = getSortType(subColumn.columnType);
        subColumn.Cell = getCellTypeRenderer(subColumn.columnType);
      }
    }

    if (column.columnType) {
      column.alignment = column.alignment
        ? column.alignment
        : getAlignmentBasedOnType(column.columnType);
      column.Cell = getCellTypeRenderer(column.columnType);
    }
  }

  return columns as Column<D>[];
}

/** get sorting function for each of the different columntypes so the values are sorted correctly */
function getSortType(columnType?: ColumnType): CompareRows {
  switch (columnType) {
    case 'number':
    case 'bit':
      return numberlikeCompare;
    case 'date':
      return datelikeCompare;
    default:
      return stringlikeCompare;
  }
}

/** get text alignment of column based on columntype */
function getAlignmentBasedOnType(columnType: ColumnType): Alignment {
  switch (columnType) {
    case 'number':
    case 'bit':
    case 'date':
      return 'right';
    default:
      return 'left';
  }
}

type CellTypeRenderer = ({
  value,
  column,
}: {
  value: any;
  column: ExtendedColumn<SparklineColumnConfig | MeterbarColumnConfig>;
}) => React.ReactNode;

/** Creates a cell render function that returns a ReactNode for a given value. */
function createFormattedCellRenderer(
  formatter: (value: any) => React.ReactNode,
): ({ value }: { value: any }) => React.ReactNode {
  return ({ value }) => {
    if (value !== undefined && value !== null) {
      return formatter(value.cellValue ?? value);
    }

    return '';
  };
}

const CELL_TYPE_RENDERERS: Record<ColumnType, CellTypeRenderer> = {
  number: createFormattedCellRenderer((value) => {
    const valueAsNumber = Number.isNaN(+value)
      ? ''
      : _convertToNumberIfPureNumber(value);

    return typeof valueAsNumber === 'number'
      ? adjustFractionDigits(valueAsNumber)
      : '';
  }),
  bit: createFormattedCellRenderer((value) => {
    const valueAsNumber = Number.isNaN(+value)
      ? ''
      : _convertToNumberIfPureNumber(value);

    return typeof valueAsNumber === 'number'
      ? format(value, { input: units.data.bit })
      : '';
  }),
  date: createFormattedCellRenderer((value) => {
    return <>{_formatDate(new Date(_convertToNumberIfPureNumber(value)))}</>;
  }),
  text: createFormattedCellRenderer((value) => `${value}`),
  sparkline: ({
    value,
    column,
  }: {
    value: Timeseries[];
    column: ExtendedColumn<SparklineColumnConfig>;
  }) => (
    <Sparkline
      data={value}
      color={
        (column.config?.color as string) ||
        Colors.Charts.Categorical.Color01.Default
      }
      variant={column.config?.variant || 'line'}
    ></Sparkline>
  ),
  meterbar: ({
    value,
    column,
  }: {
    value: number | { name: string; value: number; color?: string }[];
    column: ExtendedColumn<MeterbarColumnConfig>;
  }) => {
    return meterBarChart(value, column);
  },
};

/**
 * Returns matching cell renderer for each of the different column types so
 * the values are displayed correctly.
 */
export function getCellTypeRenderer(
  columnType: ColumnType,
): ({ value }: { value: any }) => React.ReactNode {
  return CELL_TYPE_RENDERERS[columnType] ?? CELL_TYPE_RENDERERS.text;
}

/** Table hook that enables column types */
export function useColumnTypes<
  D extends Record<string, unknown> = Record<string, unknown>,
>(hooks: Hooks<D>): void {
  hooks.columns.push(applyColumnTypes);
}
